const fs = require('node:fs');
const dir = 'products/services/contracts-finder-small-data-job';
const required = ['official-feed.json', 'buyer-scope-readback.json', 'source-verified-triage.json', 'pinned-buyer-decision-input.json'];
const files = fs.readdirSync(dir).sort();
const verdictFiles = files.filter(name => /verdict|no-bid|decision-result|bounded-result/i.test(name));
console.log(JSON.stringify({files, verdictFiles}));
for (const name of [...required, ...verdictFiles]) {
  const path = `${dir}/${name}`;
  if (!fs.existsSync(path)) continue;
  const raw = fs.readFileSync(path);
  const sha256 = require('node:crypto').createHash('sha256').update(raw).digest('hex');
  const data = JSON.parse(raw.toString('utf8'));
  if (name === 'official-feed.json') {
    const releases = data.releases ?? [];
    console.log(JSON.stringify({path, sha256, releases: releases.map(({id, tender}) => ({id, title: tender?.title, description: tender?.description?.slice(0, 600), lots: tender?.lots?.map(({title, description}) => ({title, description: description?.slice(0, 350)})), deadline: tender?.tenderPeriod?.endDate}))}));
  } else {
    console.log(JSON.stringify({path, sha256, evidence: JSON.stringify(data).slice(0, 2500)}));
  }
}
